-- Database-side protection: the publishable key is public, so these rules are the real security.

-- Ids are generated by the database (the app used to compute max+1, which races).
alter table "Report" alter column "REP_id" add generated by default as identity;
select setval(pg_get_serial_sequence('"Report"', 'REP_id'), coalesce(max("REP_id"), 0) + 1, false)
from "Report";

alter table "Report" alter column "user_id" set default auth.uid();

-- Input limits, also enforced in the forms.
alter table "Report"
  add constraint report_libelle_length check (char_length(btrim("REP_libelle")) between 3 and 150),
  add constraint report_content_length check (char_length("REP_content") between 1 and 5000),
  add constraint report_solution_length check (char_length("REP_solution") <= 5000);
alter table "Base"      add constraint base_libelle_length  check (char_length(btrim("BAS_libelle")) between 1 and 60);
alter table "Asset"     add constraint asset_name_length    check (char_length(btrim("AS_name")) between 1 and 60);
alter table "AssetType" add constraint type_libelle_length  check (char_length(btrim("AT_libelle")) between 1 and 60);
alter table "Tag"       add constraint tag_libelle_length   check (char_length(btrim("TAG_libelle")) between 1 and 60);

-- No duplicate labels, whatever the case.
create unique index base_libelle_unique on "Base" (lower("BAS_libelle"));
create unique index asset_name_unique   on "Asset" (lower("AS_name"));
create unique index type_libelle_unique on "AssetType" (lower("AT_libelle"));
create unique index tag_libelle_unique  on "Tag" (lower("TAG_libelle"));

/** True when the caller's JWT carries the admin role, which only the server can set (app_metadata). */
create function public.is_admin() returns boolean
language sql stable set search_path = ''
as $$ select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin', false) $$;

-- Columns a regular user must not control: author, creation date, validation.
create function public.protect_report_columns() returns trigger
language plpgsql set search_path = ''
as $$
begin
  -- Server-side callers (seed, service role) have no user and are trusted.
  if auth.uid() is null then return new; end if;
  if tg_op = 'INSERT' then
    new."user_id" := auth.uid();
    new."REP_created_at" := now();
    if not public.is_admin() then new."REP_is_solution_validated" := false; end if;
  else
    new."REP_id" := old."REP_id";
    new."user_id" := old."user_id";
    new."REP_created_at" := old."REP_created_at";
    if not public.is_admin() then
      new."REP_is_solution_validated" := old."REP_is_solution_validated"
        and new."REP_solution" is not distinct from old."REP_solution";
    end if;
  end if;
  return new;
end $$;

create trigger protect_report_columns before insert or update on "Report"
for each row execute function public.protect_report_columns();

-- Replace the permissive policies of the init migration.
drop policy "all" on "Report";
drop policy "all" on "ReportHasTag";

create policy "read" on "Report" for select to authenticated using (true);
create policy "create own" on "Report" for insert to authenticated with check (true);
create policy "edit own or admin" on "Report" for update to authenticated
  using ("user_id" = auth.uid() or public.is_admin());
create policy "delete own or admin" on "Report" for delete to authenticated
  using ("user_id" = auth.uid() or public.is_admin());

create policy "read" on "ReportHasTag" for select to authenticated using (true);
create policy "tag own or admin" on "ReportHasTag" for insert to authenticated
  with check (exists (select 1 from "Report" r where r."REP_id" = "ReportHasTag"."REP_id"
                      and (r."user_id" = auth.uid() or public.is_admin())));
create policy "untag own or admin" on "ReportHasTag" for delete to authenticated
  using (exists (select 1 from "Report" r where r."REP_id" = "ReportHasTag"."REP_id"
                 and (r."user_id" = auth.uid() or public.is_admin())));

-- Anyone signed in can add a category, asset, type or tag; only admins rename or delete them.
do $$
declare t text;
begin
  foreach t in array array['Base', 'Asset', 'AssetType', 'Tag'] loop
    execute format('create policy "create" on %I for insert to authenticated with check (true)', t);
    execute format('create policy "admin edit" on %I for update to authenticated using (public.is_admin())', t);
    execute format('create policy "admin delete" on %I for delete to authenticated using (public.is_admin())', t);
  end loop;
end $$;

-- The anonymous role never needs these tables.
revoke all on "Base", "Asset", "AssetType", "Tag", "Report", "ReportHasTag" from anon;
